#include <stdio.h>
#include <stdint.h>

#define MAX_CH      8
#define MAX_SAMPLES 256

static uint16_t samples[MAX_CH][MAX_SAMPLES];

/* Average of n 12-bit samples, rounded to nearest. */
static uint16_t adc_average(const uint16_t *s, uint16_t n)
{
